#include <algorithm>
#include <concepts>
#include <iterator>
#include <list>
#include <ranges>
#include <vector>

template <std::random_access_iterator It>
    requires std::sortable<It>
void sort_all(It first, It last) {
    std::sort(first, last);
}

template <typename C>
concept HasSize = requires (const C& c) {
    { c.size() } -> std::convertible_to<std::size_t>;   // must compile, returns size-like.
};

template <HasSize C>
bool is_empty(const C& c) { return c.size() == 0; }

int main() {
    std::vector<int> v{3, 1, 2};
    sort_all(v.begin(), v.end());                    // ok.
    std::list<int> l{3, 1, 2};
    // sort_all(l.begin(), l.end());   error: constraint random_access_iterator not satisfied.
    l.sort();                                        // the list's own sort.
    bool e = is_empty(v);                            // false.
    (void)e;
}
